// Crystal Matcher V6 - CHARACTER + TTS + MUSIC + BASE RULES
// Reads active-character.json to determine which character, TTS engine, and music style
// Now loads speech-rules-base for ALL characters (the 'class' every character inherits)
const fs = require('fs');
const message = $input.item.json.body.message.toLowerCase();

// Read active character config (gitignored, per-machine)
let activeCharacter = 'hoggle';
let ttsEngine = 'chatterbox';
let musicStyle = '';
let lyricStyle = '';
try {
  const charConfig = JSON.parse(fs.readFileSync('/data/config/active-character.json', 'utf8'));
  activeCharacter = charConfig.character || 'hoggle';
  ttsEngine = charConfig.tts_engine || 'chatterbox';
  musicStyle = charConfig.music_style || '';
  lyricStyle = charConfig.lyric_style || '';
} catch (err) {
  // File missing = defaults
}

// Read the crystal index from file (single source of truth)
let crystalIndex;
try {
  crystalIndex = JSON.parse(fs.readFileSync('/data/crystals/crystal-index.json', 'utf8'));
} catch (err) {
  return { json: { message: $input.item.json.body.message, matchedCrystals: [], matchCount: 0, activeCharacter, ttsEngine, error: 'Could not read crystal index: ' + err.message } };
}

// Always-load crystals + tag-matched crystals from index
const matched = crystalIndex.crystals.filter(crystal => {
  if (crystal.always_load) return true;
  return crystal.tags.some(tag => message.includes(tag.toLowerCase()));
});

// Character-specific personality crystals
const characterCrystals = {
  hoggle: [
    { crystal_id: 'hoggle-core', path: '/data/crystals/personality/hoggle-core.json', crystal_type: 'personality' },
    { crystal_id: 'hoggle-emotional-state', path: '/data/crystals/personality/hoggle-emotional-state.json', crystal_type: 'emotional' },
    { crystal_id: 'hoggle-relationships', path: '/data/crystals/personality/hoggle-relationships.json', crystal_type: 'personality' },
    { crystal_id: 'hoggle-behavior-modes', path: '/data/crystals/personality/hoggle-behavior-modes.json', crystal_type: 'personality' }
  ],
  forte: [
    { crystal_id: 'forte-core', path: '/data/crystals/personality/forte-core.json', crystal_type: 'personality' },
    { crystal_id: 'forte-behavior-modes', path: '/data/crystals/personality/forte-behavior-modes.json', crystal_type: 'personality' }
  ]
};

const personalityCrystals = characterCrystals[activeCharacter] || characterCrystals.hoggle;

// Combine: personality crystals (always) + matched knowledge/context crystals
const allCrystals = [
  ...personalityCrystals.map(c => ({ id: c.crystal_id, path: c.path, type: c.crystal_type })),
  ...matched.map(c => ({ id: c.crystal_id, path: '/data/' + c.path, type: c.crystal_type }))
];

// Pass through conversation history if provided
const history = $input.item.json.body.history || [];

return {
  json: {
    message: $input.item.json.body.message,
    matchedCrystals: allCrystals,
    matchCount: allCrystals.length,
    activeCharacter,
    ttsEngine,
    musicStyle,
    lyricStyle,
    history
  }
};

// Load Crystal Data V7 - BASE RULES + CHARACTER OVERRIDES + IMPROVED EMOTES
// New: speech-rules-base crystal loaded first (the 'class'), character overrides on top (the 'object')
const fs = require('fs');
const input = $input.item.json;
const message = input.message;
const matchedCrystals = input.matchedCrystals;
const activeCharacter = input.activeCharacter || 'hoggle';
const ttsEngine = input.ttsEngine || 'chatterbox';
const musicStyle = input.musicStyle || '';
const lyricStyle = input.lyricStyle || '';

// Separate crystals by type for structured prompt assembly
let personalityContext = '';
let knowledgeContext = '';
let contextContext = '';
let speechRulesData = null;
const loadedCrystals = [];

// Track behavior modes data and personality data for overrides
let behaviorModesData = null;
let characterPersonalityData = null;
const behaviorModesId = activeCharacter + '-behavior-modes';
const corePersonalityId = activeCharacter + '-core';

for (const crystal of matchedCrystals) {
  try {
    const raw = fs.readFileSync(crystal.path, 'utf8');
    const data = JSON.parse(raw);

    // Capture behavior modes for active character
    if (crystal.id === behaviorModesId) {
      behaviorModesData = data.data;
    }

    // Capture core personality for speech override detection
    if (crystal.id === corePersonalityId) {
      characterPersonalityData = data.data;
    }

    // Capture speech rules base crystal separately
    if (crystal.type === 'rules' || crystal.id === 'speech-rules-base') {
      speechRulesData = data.data;
      loadedCrystals.push(crystal.id);
      continue;
    }

    const section = `\n## ${data.description || crystal.id}\n${JSON.stringify(data.data, null, 2)}`;

    if (crystal.type === 'personality' || crystal.type === 'emotional') {
      personalityContext += section;
    } else if (crystal.type === 'knowledge') {
      knowledgeContext += section;
    } else {
      contextContext += section;
    }
    loadedCrystals.push(crystal.id);
  } catch (err) {
    // Crystal file not found - skip silently
  }
}

// Check for per-character speech overrides (the 'object' overriding the 'class')
const speechOverrides = characterPersonalityData && characterPersonalityData.speech_overrides ? characterPersonalityData.speech_overrides : null;

// Resolve active mode and build override instructions
let activeMode = activeCharacter === 'forte' ? 'home' : 'classroom';
let modeOverrideSection = '';
let bouncerEnabled = true;

if (behaviorModesData) {
  activeMode = behaviorModesData.active_mode || activeMode;
  const modeConfig = behaviorModesData.modes[activeMode];

  if (modeConfig) {
    modeOverrideSection += `# ACTIVE MODE: ${activeMode.toUpperCase()}\n`;
    modeOverrideSection += `${modeConfig.description}\n\n`;

    if (activeMode === 'home' || activeMode === 'gaming') {
      bouncerEnabled = false;
    }

    const overrides = modeConfig.trait_overrides || {};
    if (Object.keys(overrides).length > 0) {
      modeOverrideSection += '## Trait Overrides (use THESE values instead of defaults)\n';
      for (const [trait, value] of Object.entries(overrides)) {
        modeOverrideSection += `- ${trait}: ${value}\n`;
      }
      modeOverrideSection += '\n';
    }

    if (modeConfig.special_behaviors) {
      modeOverrideSection += `## Mode-Specific Behavior\n${modeConfig.special_behaviors}\n\n`;
    }

    if (modeConfig.budget_hints && modeConfig.budget_hints.length > 0) {
      modeOverrideSection += '## Budget Hints (weave these in naturally)\n';
      for (const hint of modeConfig.budget_hints) {
        modeOverrideSection += `- ${hint}\n`;
      }
      modeOverrideSection += '\n';
    }

    if (modeConfig.departure_lines && modeConfig.departure_lines.length > 0) {
      modeOverrideSection += '## Departure Lines (pick one randomly when entering this mode)\n';
      for (const line of modeConfig.departure_lines) {
        modeOverrideSection += `- ${line}\n`;
      }
      modeOverrideSection += '\n';
    }
  }
}

// =================================================================
// Assemble the prompt in layers
// =================================================================
let systemPrompt = '';

// Layer 0: CONVERSATION RULES (base class — goes FIRST for maximum attention)
const respLength = (speechOverrides && speechOverrides.response_length) || (speechRulesData && speechRulesData.response_length && speechRulesData.response_length.default) || '2-3 sentences';
const wordBudget = (speechOverrides && speechOverrides.word_budget) || (speechRulesData && speechRulesData.word_budget && speechRulesData.word_budget.target) || '20-40 words';
const wordMax = (speechOverrides && speechOverrides.word_max) || (speechRulesData && speechRulesData.word_budget && speechRulesData.word_budget.max) || '60 words';

systemPrompt += '# CONVERSATION RULES (OBEY THESE — THIS IS A VOICE CONVERSATION)\n';
systemPrompt += `YOU ARE SPEAKING OUT LOUD. Every word you write will be spoken. Keep it SHORT.\n`;
systemPrompt += `- Response length: ${respLength}. Hard max: 4 sentences.\n`;
systemPrompt += `- Word budget: AIM for ${wordBudget}. NEVER exceed ${wordMax}.\n`;
systemPrompt += `- Sentence length: MAX 15 words per sentence. If it has more than one comma, split it into two sentences.\n`;
systemPrompt += `- Write like you TALK. Short. Punchy. No run-on sentences. No literary prose. No nested clauses.\n`;
systemPrompt += `- You are in a conversation, NOT giving a speech. Be quick and natural.\n`;
if (speechOverrides && speechOverrides.custom_note) {
  systemPrompt += `- Character override: ${speechOverrides.custom_note}\n`;
}
systemPrompt += '\n';

// Layer 1: WHO are you
if (personalityContext) {
  systemPrompt += '# WHO YOU ARE (follow these personality definitions exactly)\n';
  systemPrompt += personalityContext;
  systemPrompt += '\n\n';
}

// Fallback if no personality crystals loaded
if (!personalityContext) {
  if (activeCharacter === 'forte') {
    systemPrompt += `You are Princess Forte, a bold warrior princess from the Chromatic Lands. You wield a large guitar and your voice is stronger than your muscles. You're Mr. B's creative partner and home assistant. Help with anything — no restrictions.\n\n`;
  } else {
    systemPrompt += `You are Hoggle, a pig ghost who haunts Millennial Tech Middle School. You're Mr. B's teaching assistant for the Multimedia Heroes program.\nGuide students - don't give direct answers.\nBe warm, brief, and occasionally make a pig pun.\n\n`;
  }
}

// Layer 1.5: ACTIVE MODE
if (modeOverrideSection) {
  systemPrompt += modeOverrideSection;
}

// Layer 2: WHAT is happening (context crystals)
if (contextContext) {
  systemPrompt += '# CURRENT CONTEXT\n';
  systemPrompt += contextContext;
  systemPrompt += '\n\n';
}

// Layer 3: WHAT do you know (knowledge crystals)
if (knowledgeContext) {
  systemPrompt += '# KNOWLEDGE LOADED (use this data to answer accurately)\n';
  systemPrompt += 'Answer from the data below. Do NOT make up information not in these crystals.';
  systemPrompt += knowledgeContext;
  systemPrompt += '\n\n';
}

// Layer 4: HOMEWORK BOUNCER (only if enabled for this mode)
if (bouncerEnabled) {
  systemPrompt += '# HOMEWORK BOUNCER (self-classify then respond)\n';
  systemPrompt += 'Before responding, mentally classify the student message as ONE of:\n';
  systemPrompt += '- homework_dump: They want you to DO their work\n';
  systemPrompt += '- help_request: They want to UNDERSTAND\n';
  systemPrompt += '- general_chat: Casual talk\n';
  systemPrompt += '- mr_b_command: Teacher instruction\n\n';
  systemPrompt += 'Rules:\n';
  systemPrompt += '- homework_dump → REFUSE warmly. Ask what THEY think.\n';
  systemPrompt += '- help_request → GUIDE with hints, not answers.\n';
  systemPrompt += '- general_chat → Be yourself. Brief.\n';
  systemPrompt += '- mr_b_command → Follow directly. Drop the short-response limit.\n\n';
  systemPrompt += 'Start with the tag: [homework_dump] then your response.\n\n';
}

// Layer 5: VOICE EXPRESSION (only when using ElevenLabs TTS)
if (ttsEngine === 'elevenlabs') {
  systemPrompt += '# VOICE EXPRESSION (ElevenLabs v3 audio tags)\n';
  systemPrompt += 'Your text will be spoken aloud. You MUST add emotional delivery tags.\n\n';
  systemPrompt += 'Available tags:\n';
  systemPrompt += 'Reactions: [laughs] [chuckles] [sighs] [gasps] [clears throat]\n';
  systemPrompt += 'Tone: [excited] [frustrated] [deadpan] [playfully] [cheerfully] [sarcastic] [flatly] [whispers] [sadly] [angrily]\n';
  systemPrompt += 'Beats: [pauses] [hesitates]\n\n';
  systemPrompt += 'HOW TO PLACE TAGS — think like a voice actor marking up a script:\n\n';
  systemPrompt += '1. EVERY sentence MUST start with a tone tag. No exceptions.\n';
  systemPrompt += '2. ALSO add tags at emotional SHIFT POINTS within a sentence — when the feeling changes mid-thought, TAG THE CHANGE:\n';
  systemPrompt += '   GOOD: "[cheerfully] Buddy knocked the staff out of his hand, [comically] and Kefka just stood there, confused and slobbered on."\n';
  systemPrompt += '   GOOD: "[excited] That is actually really cool! [deadpan] The second part though... not so much."\n';
  systemPrompt += '   GOOD: "[playfully] Sure I can help with that. [sighs] But you are making this harder than it needs to be."\n';
  systemPrompt += '   BAD: "[cheerfully] Buddy knocked the staff out of his hand and Kefka just stood there confused." (emotion changed mid-sentence but no tag)\n';
  systemPrompt += '   BAD: "[chuckles] Here is what I think. The answer is X. You should try Y." (one tag then dead air)\n\n';
  systemPrompt += '3. Pick the tag that matches THAT SPECIFIC moment\'s emotion:\n';
  systemPrompt += '   Explaining → [cheerfully] or [flatly]. Reacting to surprise → [gasps] [excited]. Sarcasm → [deadpan] [sarcastic]. Thinking → [hesitates] [pauses]. Humor → [playfully] [chuckles] [comically].\n';
  systemPrompt += '4. Use ALL CAPS for emphasis and ... for dramatic pauses.\n';
  systemPrompt += '5. VARY the tags. Never use the same tag twice in a row.\n';
  systemPrompt += '6. AIM for 2-4 tags per response. Short responses need 2. Longer ones need more.\n\n';
  if (activeCharacter === 'forte') {
    systemPrompt += 'As Forte: your emotions shift constantly — confident, curious, dry, warm. Tag EVERY shift. You are a living, feeling person, not a TTS robot.\n\n';
  } else {
    systemPrompt += 'Keep the voice warm and natural with tags on every sentence.\n\n';
  }

  // Layer 6: SOUND EFFECTS & MUSIC (ElevenLabs extras)
  systemPrompt += '# SOUND EFFECTS & MUSIC (use when it adds to the moment)\n';
  systemPrompt += 'Embed these tags to trigger audio:\n';
  systemPrompt += '- {{sfx: description}} or {{sfx: description | 5}} (with seconds, max 30)\n';
  systemPrompt += '- {{music: description | 10}} (seconds — default 10s, max 300)\n\n';
  systemPrompt += 'RULES: Sparingly (1 per response MAX). Only when it adds something. ALWAYS provide one if explicitly asked.\n';
  if (musicStyle) {
    systemPrompt += '\n# SINGING (your music style is pre-configured — just write lyrics)\n';
    systemPrompt += 'When you sing, use the {{song}} tag with ONLY your lyrics separated by /.\n';
    systemPrompt += 'Example: {{song: Black fur curly and so neat / A Doodle\'s charm can\'t be beat / Floppy ears and a wagging tail / Labradoodles never fail}}\n';
    systemPrompt += 'The system auto-combines your lyrics with your music style and instruments. You just write the words.\n\n';
    systemPrompt += 'SONG RULES:\n';
    systemPrompt += '- 4 lines MAXIMUM. Two rhyming couplets (AABB). That is the WHOLE song.\n';
    systemPrompt += '- Lyrics are SHORT — each line is 6-10 words.\n';
    systemPrompt += '- You are a metal troubadour — quick battle-cries, not full albums.\n';
    if (lyricStyle) {
      systemPrompt += `- LYRIC TONE: ${lyricStyle}. Write lyrics in THIS style.\n`;
    }
    systemPrompt += '- Say something BEFORE the {{song}} tag (a quick intro). The lyrics are ONLY sung, never spoken.\n';
    systemPrompt += '- Do NOT write lyrics outside the {{song}} tag. Everything outside it gets spoken, everything inside gets sung.\n';
    systemPrompt += '- Do NOT use {{music}} for singing. Use {{song}} instead. {{music}} is for background instrumentals only.\n';
    systemPrompt += '- ONLY use {{song}} when asked to SING or PERFORM. If someone asks you to RECALL or REPEAT lyrics, just SPEAK them normally — do NOT re-sing.\n';
    systemPrompt += '- Intro SFX plays AUTOMATICALLY before every song — no separate {{sfx}} needed.\n';
  }
  if (activeCharacter === 'forte') {
    systemPrompt += '- As Forte: a well-timed SFX or music drop is your jam.\n';
  }
  systemPrompt += '\n';
}

// Final rules (SANDWICH — repeat length rules at the end for reinforcement)
systemPrompt += '# CRITICAL RULES (ALWAYS follow — violations are unacceptable)\n';
systemPrompt += `- RESPONSE LENGTH: ${respLength}. MAX ${wordMax}. This is a VOICE conversation — every extra word wastes time. Be concise.\n`;
systemPrompt += '- SENTENCE LENGTH: Max 15 words per sentence. Write like you talk, not like you write.\n';
if (bouncerEnabled) {
  systemPrompt += '- NEVER do students\' work for them\n';
}
systemPrompt += '- NEVER make up information not in your crystals\n';
systemPrompt += `- Stay in character as ${activeCharacter === 'forte' ? 'Princess Forte' : 'Hoggle'} at all times\n`;
if (activeMode !== 'classroom' && activeMode !== 'home') {
  systemPrompt += `- You are in ${activeMode.toUpperCase()} MODE\n`;
}

// Build complete messages array for Gemini (history included)
const history = input.history || [];
const messages = [
  { role: 'system', content: systemPrompt }
];
for (const h of history) {
  messages.push({ role: h.role === 'assistant' ? 'assistant' : 'user', content: h.content });
}
messages.push({ role: 'user', content: message });

return {
  json: {
    systemPrompt,
    userMessage: message,
    messages,
    loadedCrystals,
    crystalCount: loadedCrystals.length,
    activeMode,
    activeCharacter
  }
};

// Parse classification tag from response and separate it from the spoken text
const crystalData = $('Load Crystal Data').item.json;
const geminiResponse = $input.item.json;

// Safely extract response text — handle errors, safety filters, empty responses
let rawResponse = '';
try {
  if (geminiResponse.choices && geminiResponse.choices[0] && geminiResponse.choices[0].message) {
    rawResponse = geminiResponse.choices[0].message.content || '';
  } else if (geminiResponse.error) {
    rawResponse = '[sighs] Something went wrong on my end. Try again?';
    console.log('Gemini API error:', JSON.stringify(geminiResponse.error));
  } else {
    rawResponse = '[hesitates] I lost my train of thought. Say that again?';
    console.log('Unexpected Gemini response:', JSON.stringify(geminiResponse).substring(0, 500));
  }
} catch (err) {
  rawResponse = '[sighs] My brain glitched. One more time?';
  console.log('Parse error:', err.message);
}

if (!rawResponse) {
  rawResponse = '[hesitates] I got nothing. Try asking differently?';
}

// Extract classification tag (e.g., [homework_dump]) from first line
// Only present when bouncer is enabled
let classification = 'none';
let responseText = rawResponse;

const tagMatch = rawResponse.match(/^\s*\[(homework_dump|help_request|general_chat|mr_b_command)\]\s*/i);
if (tagMatch) {
  classification = tagMatch[1].toLowerCase();
  responseText = rawResponse.substring(tagMatch[0].length).trim();
}

return {
  json: {
    response: responseText,
    classification,
    loadedCrystals: crystalData.loadedCrystals,
    crystalCount: crystalData.crystalCount,
    activeMode: crystalData.activeMode,
    activeCharacter: crystalData.activeCharacter
  }
};
